fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Assume x and y are non-empty as stated.
    let mut xx: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut yy: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &y_i in &y {
        // First grid: each row is a copy of x
        xx.push(x.clone());

        // Second grid: each row is filled with the corresponding y value
        yy.push(vec![y_i; cols]);
    }

    (xx, yy)
}